// Exact built-in titles only. User/source wording is retained, never rewritten.
const frenchFindingTitles = {
    "Period close preflight unavailable": "Contrôle préalable à la clôture indisponible",
    "Trial balance is out of balance": "La balance générale est déséquilibrée",
    "Ledger reconciliation unavailable": "Rapprochement du grand livre indisponible",
    "Payment reconciliation evidence unavailable": "Justificatifs du rapprochement des paiements indisponibles",
    "Data-trust evidence unavailable": "Justificatifs de fiabilité des données indisponibles",
    "Payroll forecast proof is unavailable": "Justificatifs des prévisions de paie indisponibles",
    "Payroll finance forecast proof is blocked": "Justificatifs des prévisions financières de paie bloqués",
    "No accounting period": "Aucune période comptable",
};
function closeEvidenceFindingTitle(title, locale) {
    return locale === "fr" && Object.hasOwn(frenchFindingTitles, title) ? frenchFindingTitles[title] : title;
}


